"""Atlas: inspect finite current-identity classifications without reading or changing processes."""
import importlib.util,json,hashlib
from pathlib import Path
R=Path(__file__).resolve().parent;s=importlib.util.spec_from_file_location('gate',R/'resource-gate.py');g=importlib.util.module_from_spec(s);s.loader.exec_module(g);p=json.loads((R/'gate-policy.json').read_text());known=[{k:v for k,v in x.items() if k!='cpu_percent_at_most'}|{'cpu':0.0} for x in p['known_idle_identities']];assert len(known)==2
other={'pid':999999,'ppid':1,'lstart':'synthetic','comm':'/usr/bin/other','cpu':0.0};tests=[('both_match',known,True,True),('both_absent',[other],True,True),('one_absent',known[:1],True,True),('reused_nonruntime',[known[0]|{'comm':'/usr/bin/python3'}],True,False),('new_start',[known[0]|{'lstart':'changed'}],True,False),('new_parent',[known[0]|{'ppid':2}],True,False),('cpu_boundary',[known[1]|{'cpu':1.0}],True,True),('cpu_above',[known[1]|{'cpu':1.1}],True,False),('unknown_java',known+[other|{'comm':'/unknown/java'}],True,False),('headless',[other|{'comm':'/unknown/chrome-headless-shell'}],True,False),('incomplete',known,False,False),('empty',[],True,False)];results=[]
for name,rows,complete,expected in tests:
 actual=g.assess(rows,p,complete);assert actual['process_condition_passed'] is expected;results.append({'case':name,'expected':expected,'observed':actual})
report={'title':'Atlas analytics current identity finite checks','passed':True,'cases':results,'actual_process_observations':0,'target_started':False,'sources':{n:hashlib.sha256((R/n).read_bytes()).hexdigest() for n in ['resource-gate.py','gate-policy.json','check-identities.py']}};(R/'observations/identity-classification-check.json').write_text(json.dumps(report,indent=2)+'\n');print(json.dumps({'passed':True,'cases':len(results)}))
